import{_ as a}from"./chunks/cynefin-OW5HDTMX.rPCZ-tep.js";import{o as i,c as s,a as t}from"./chunks/mermaid.C1W4YCqa.js";import"./chunks/mermaid-utils.B0bJactl.js";import"./chunks/mermaid-graph.C5JX3QLV.js";import"./chunks/mermaid-layout.DzVnZVT_.js";const b=JSON.parse(`{"title":"What's new in v2.0.0","description":"Hierarchical team-prefix grouping with nested headings, auto-pick, and exclusions — plus GCS_DEFAULT_ORG and gh CLI token fallback. Breaking change to --group-by-team-prefix and JSON output.","frontmatter":{"title":"What's new in v2.0.0","description":"Hierarchical team-prefix grouping with nested headings, auto-pick, and exclusions — plus GCS_DEFAULT_ORG and gh CLI token fallback. Breaking change to --group-by-team-prefix and JSON output.","date":"2026-09-19T00:00:00.000Z"},"headers":[],"relativePath":"blog/release-v2-0-0.md","filePath":"blog/release-v2-0-0.md"}`),n={name:"blog/release-v2-0-0.md"};function o(l,e,r,h,d,p){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="what-s-new-in-github-code-search-v2-0-0" tabindex="-1">What&#39;s new in github-code-search v2.0.0 <a class="header-anchor" href="#what-s-new-in-github-code-search-v2-0-0" aria-label="Permalink to &quot;What&#39;s new in github-code-search v2.0.0&quot;">​</a></h1><blockquote><p>Full release notes: <a href="https://github.com/fulll/github-code-search/releases/tag/v2.0.0" target="_blank" rel="noreferrer">https://github.com/fulll/github-code-search/releases/tag/v2.0.0</a></p></blockquote><p>This is a <strong>major</strong> release: <code>--group-by-team-prefix</code> now supports a full hierarchy instead of a single flat level, which changes the markdown heading structure and the JSON output shape for anyone already using it. See <a href="#breaking-changes">Breaking changes</a> below before upgrading.</p><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><h3 id="hierarchical-team-prefix-grouping" tabindex="-1">Hierarchical team-prefix grouping <a class="header-anchor" href="#hierarchical-team-prefix-grouping" aria-label="Permalink to &quot;Hierarchical team-prefix grouping&quot;">​</a></h3><p><code>--group-by-team-prefix</code> now accepts a small chain grammar instead of a flat, comma-separated prefix list:</p><ul><li><code>/</code> nests levels <strong>within one chain</strong> — group by the first prefix, then sub-group each section by the next prefix.</li><li><code>,</code> separates <strong>independent chains</strong> — each grouped on its own, against whatever repos earlier chains haven&#39;t already claimed.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#6A737D;"># Group by tribe- first, then by squad- within each tribe</span></span>\n<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;">  --group-by-team-prefix</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> tribe-/squad-</span></span></code></pre></div><p>Markdown output renders one heading level per depth (<code>##</code>, <code>###</code>, <code>####</code>, … capped at H6), and JSON output now carries the full hierarchy per result as a <code>section</code> array:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#024C1A;--shiki-dark:#79B8FF;">  &quot;repo&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;">&quot;myorg/mobile-app&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#024C1A;--shiki-dark:#79B8FF;">  &quot;section&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;">&quot;tribe-b&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;">&quot;squad-core + squad-mobile&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">],</span></span>\n<span class="line"><span style="--shiki-light:#024C1A;--shiki-dark:#79B8FF;">  &quot;matches&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">: [{ </span><span style="--shiki-light:#024C1A;--shiki-dark:#79B8FF;">&quot;path&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;">&quot;src/index.ts&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#024C1A;--shiki-dark:#79B8FF;">&quot;url&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#024C1A;--shiki-dark:#79B8FF;">&quot;line&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#024C1A;--shiki-dark:#79B8FF;">&quot;col&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;"> }]</span></span>\n<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Team names that overlap within one level (e.g. <code>squad-a</code> and <code>squad-a-legacy</code>) are now <strong>combined automatically</strong> into one section instead of appearing as unrelated siblings.</p><h3 id="pick-team-at-every-hierarchy-level" tabindex="-1"><code>--pick-team</code> at every hierarchy level <a class="header-anchor" href="#pick-team-at-every-hierarchy-level" aria-label="Permalink to &quot;`--pick-team` at every hierarchy level&quot;">​</a></h3><p><code>--pick-team</code> and interactive pick mode (<code>p</code>) now resolve combined sections at <strong>any depth</strong> of the hierarchy, not just the top level — the same workflow from v1.11.0, extended to nested chains.</p><h3 id="pick-team-auto-—-resolve-ambiguous-sections-automatically" tabindex="-1"><code>--pick-team-auto</code> — resolve ambiguous sections automatically <a class="header-anchor" href="#pick-team-auto-—-resolve-ambiguous-sections-automatically" aria-label="Permalink to &quot;`--pick-team-auto` — resolve ambiguous sections automatically&quot;">​</a></h3><p>New flag: auto-resolves combined sections whose team names share a common prefix (e.g. <code>tribe-a + tribe-a-p1</code> → <code>tribe-a</code>), without an explicit <code>--pick-team</code>. It also clusters combos that share a recurring team across siblings even without a literal common prefix, and always defers to an explicit <code>--pick-team</code> for the same section.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;">  --group-by-team-prefix</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> tribe-/squad-</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;">  --pick-team-auto</span></span></code></pre></div><h3 id="exclude-team-prefixes-—-strip-noisy-team-names-before-grouping" tabindex="-1"><code>--exclude-team-prefixes</code> — strip noisy team names before grouping <a class="header-anchor" href="#exclude-team-prefixes-—-strip-noisy-team-names-before-grouping" aria-label="Permalink to &quot;`--exclude-team-prefixes` — strip noisy team names before grouping&quot;">​</a></h3><p>Some orgs have many closely related, deeply-overlapping team names under one prefix. <code>--exclude-team-prefixes</code> removes matching teams from consideration <strong>before</strong> grouping runs, reducing ambiguous combos at the source:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;">  --group-by-team-prefix</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> tribe-/squad-</span><span style="--shiki-light:#A0111F;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;">  --exclude-team-prefixes</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> squad-validators-</span></span></code></pre></div><h3 id="gcs-default-org-—-skip-org-on-every-call" tabindex="-1"><code>GCS_DEFAULT_ORG</code> — skip <code>--org</code> on every call <a class="header-anchor" href="#gcs-default-org-—-skip-org-on-every-call" aria-label="Permalink to &quot;`GCS_DEFAULT_ORG` — skip `--org` on every call&quot;">​</a></h3><p>If you mostly search a single organization, set it once and omit <code>--org</code> entirely:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;"> GCS_DEFAULT_ORG</span><span style="--shiki-light:#A0111F;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">my-org</span></span>\n<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag&quot;</span></span></code></pre></div><p>An explicit <code>--org</code> flag always takes precedence.</p><h3 id="github-token-fallback-via-the-github-cli" tabindex="-1"><code>GITHUB_TOKEN</code> fallback via the GitHub CLI <a class="header-anchor" href="#github-token-fallback-via-the-github-cli" aria-label="Permalink to &quot;`GITHUB_TOKEN` fallback via the GitHub CLI&quot;">​</a></h3><p>If <code>GITHUB_TOKEN</code> isn&#39;t set and the <a href="https://cli.github.com/" target="_blank" rel="noreferrer">GitHub CLI</a> is installed and authenticated, <code>github-code-search</code> now retrieves a token automatically via <code>gh auth token</code> — no extra setup needed. Applies to the search commands and the <code>upgrade</code> subcommand.</p><h3 id="also-in-this-release" tabindex="-1">Also in this release <a class="header-anchor" href="#also-in-this-release" aria-label="Permalink to &quot;Also in this release&quot;">​</a></h3><ul><li>Fixed a systematic ~2 s exit delay after printing results, in both interactive and non-interactive (<code>--no-interactive</code> / CI) mode.</li><li>Removed the <code>picocolors</code> dependency in favor of a native <code>util.styleText</code> facade — no behavior change, one less external dependency.</li><li>Bumped the minimum required Bun version to <strong>1.4</strong> (native <code>Bun.stringWidth</code> / <code>stripANSI</code> / <code>sliceAnsi</code> and <code>util.styleText</code> are used at runtime).</li><li>Routine dependency upgrades.</li></ul><h2 id="breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h2><ul><li><strong>Removed</strong> <code>--group-by-team-prefix-consolidate</code> and the underlying consolidated-rendering mode. In practice, <code>--pick-team-auto</code> covers the real need (resolving ambiguous combined sections) more reliably — if you used the consolidate flag, switch to <code>--pick-team-auto</code> and/or <code>--exclude-team-prefixes</code>.</li><li>Markdown output can now render <strong>more than one heading level</strong> (<code>##</code>/<code>###</code>/<code>####</code>…) when a multi-level chain (<code>tribe-/squad-</code>) is used, instead of always a single flat <code>##</code> level.</li><li>JSON output gains a <strong><code>section</code> array</strong> per result when <code>--group-by-team-prefix</code> is used (previously JSON carried no section/team information at all).</li></ul><p>Plain, single-level <code>--group-by-team-prefix squad-</code> usage (no <code>/</code>) is unaffected — you&#39;ll only notice a difference if you adopt the new chain syntax or previously relied on <code>--group-by-team-prefix-consolidate</code>.</p><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div><p>Or download the latest binary from <a href="https://github.com/fulll/github-code-search/releases/tag/v2.0.0" target="_blank" rel="noreferrer">GitHub Releases</a>.</p>',33)])])}const y=a(n,[["render",o]]);export{b as __pageData,y as default};
